import rawCatalog from "../config/catalog.json";
import { CEFR_LEVELS, type CatalogVideo, type CefrLevel } from "./types";

// generated by scripts/build-catalog.mjs
export const VIDEO_CATALOG = rawCatalog as CatalogVideo[];

export function videosByLevel(level: CefrLevel): CatalogVideo[] {
  return VIDEO_CATALOG.filter((v) => v.level === level);
}

export function countByLevel(): Record<CefrLevel, number> {
  return Object.fromEntries(CEFR_LEVELS.map((l) => [l, videosByLevel(l).length])) as Record<CefrLevel, number>;
}
